import React, { useState, useRef, useEffect } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';

const scaleIn = keyframes`
  from { opacity: 0; transform: scale(0.95) translateY(-6px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
`;

const Wrapper = styled.div`
  position: relative;
`;

const Trigger = styled.button`
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px 4px 4px;
  background: none;
  border: 1px solid ${theme.colors.border};
  border-radius: 999px;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  &:hover {
    border-color: ${theme.colors.accent};
    background: ${theme.colors.sidebarHover};
  }
`;

const Avatar = styled.img`
  width: 26px;
  height: 26px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
`;

const AvatarFallback = styled.div`
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: ${theme.colors.accent};
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  font-family: ${theme.typography.fontFamily};
  flex-shrink: 0;
`;

const DisplayName = styled.span`
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 600;
  color: ${theme.colors.mainText};
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`;

const Dropdown = styled.div`
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  min-width: 220px;
  background: #161b22;
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  z-index: 3000;
  overflow: hidden;
  animation: ${scaleIn} 0.15s ease;
`;

const DropdownHeader = styled.div`
  padding: 14px 16px 12px;
  border-bottom: 1px solid ${theme.colors.border};
`;

const DropdownAvatar = styled.img`
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  margin-bottom: 10px;
`;

const DropdownAvatarFallback = styled.div`
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: ${theme.colors.accent};
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  font-family: ${theme.typography.fontFamily};
  margin-bottom: 10px;
`;

const DropdownName = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 700;
  color: ${theme.colors.mainText};
`;

const DropdownEmail = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: 12px;
  color: ${theme.colors.mainTextMuted};
  margin-top: 2px;
`;

const DropdownItem = styled.button`
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  color: ${theme.colors.mainTextMuted};
  transition: background 0.12s, color 0.12s;
  &:hover {
    background: ${theme.colors.sidebarHover};
    color: #f85149;
  }
`;

export interface UserMenuUser {
  name?: string;
  email: string;
  avatarUrl?: string;
}

interface UserMenuProps {
  user: UserMenuUser;
  onSignOut: () => void;
  compact?: boolean; // avatar-only trigger, for use in app headers
}

export function UserMenu({ user, onSignOut, compact = false }: UserMenuProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  const displayName = user.name ?? user.email.split('@')[0];
  const initial = displayName[0].toUpperCase();

  return (
    <Wrapper ref={ref}>
      <Trigger onClick={() => setOpen((o) => !o)}>
        {user.avatarUrl
          ? <Avatar src={user.avatarUrl} alt={displayName} />
          : <AvatarFallback>{initial}</AvatarFallback>
        }
        {!compact && <DisplayName>{displayName}</DisplayName>}
      </Trigger>

      {open && (
        <Dropdown>
          <DropdownHeader>
            {user.avatarUrl
              ? <DropdownAvatar src={user.avatarUrl} alt={displayName} />
              : <DropdownAvatarFallback>{initial}</DropdownAvatarFallback>
            }
            <DropdownName>{displayName}</DropdownName>
            <DropdownEmail>{user.email}</DropdownEmail>
          </DropdownHeader>
          <DropdownItem onClick={() => { setOpen(false); onSignOut(); }}>
            Sign out
          </DropdownItem>
        </Dropdown>
      )}
    </Wrapper>
  );
}
