import APP_CONFIG from './apps.config';

const APP_META = Object.fromEntries(
  APP_CONFIG.map(({ id, icon, description, color, category }) => [id, { icon, description, color, category }])
);

const ALL_CATEGORIES = ['All', ...Array.from(new Set(APP_CONFIG.filter(a => a.enabled).map(a => a.category)))];

// ─── Animations ───────────────────────────────────────────────────────────────

const fadeUp = keyframes`
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const fadeIn = keyframes`
  from { opacity: 0; }
  to   { opacity: 1; }
`;

const scaleIn = keyframes`
  from { opacity: 0; transform: scale(0.96) translateY(-8px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
`;

