// ─── Component ────────────────────────────────────────────────────────────────

interface HomeScreenProps {
  apps: AppDefinition[];
  recentAppIds: string[];
  pinnedAppIds: string[];
  onTogglePin: (appId: string) => void;
  onSelect: (app: AppDefinition) => void;
  user?: { name?: string; email: string; avatarUrl?: string } | null;
  onSignOut?: () => void;
}

export function HomeScreen({ apps, recentAppIds, pinnedAppIds, onTogglePin, onSelect, user, onSignOut }: HomeScreenProps) {
  const [activeCategory, setActiveCategory] = useState('All');
  const [search, setSearch]                 = useState('');
  const [paletteOpen, setPaletteOpen]       = useState(false);
  const [paletteQuery, setPaletteQuery]     = useState('');
  const [paletteIndex, setPaletteIndex]     = useState(0);
  const paletteInputRef = useRef<HTMLInputElement>(null);
  const searchInputRef  = useRef<HTMLInputElement>(null);

  // Cmd+K / Ctrl+K opens palette
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setPaletteOpen((v) => !v);
        setPaletteQuery('');
        setPaletteIndex(0);
      }
      if (e.key === 'Escape') setPaletteOpen(false);
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  // Focus palette input when opened
  useEffect(() => {
    if (paletteOpen) setTimeout(() => paletteInputRef.current?.focus(), 30);
  }, [paletteOpen]);

  // Palette results
  const paletteResults = useMemo(() => {
    const q = paletteQuery.toLowerCase().trim();
    return apps.filter((app) => {
      if (!q) return true;
      const meta = APP_META[app.id];
      return (
        app.label.toLowerCase().includes(q) ||
        meta?.description.toLowerCase().includes(q) ||
        meta?.category.toLowerCase().includes(q)
      );
    });
  }, [apps, paletteQuery]);

  // Keep index in bounds when results change
  useEffect(() => {
    setPaletteIndex((prev) => Math.min(prev, Math.max(0, paletteResults.length - 1)));
  }, [paletteResults.length]);

  const handlePaletteKey = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setPaletteIndex((i) => Math.min(i + 1, paletteResults.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setPaletteIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      const app = paletteResults[paletteIndex];
      if (app) { setPaletteOpen(false); onSelect(app); }
    }
  }, [paletteResults, paletteIndex, onSelect]);

  // Main grid filtering
  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return apps.filter((app) => {
      const meta = APP_META[app.id];
      const matchesCategory = activeCategory === 'All' || meta?.category === activeCategory;
      const matchesSearch = !q || app.label.toLowerCase().includes(q) || meta?.description.toLowerCase().includes(q);
      return matchesCategory && matchesSearch;
    });
  }, [apps, activeCategory, search]);

  const grouped = useMemo(() => {
    if (activeCategory !== 'All' || search) return null;
    const groups: Record<string, AppDefinition[]> = {};
    for (const app of filtered) {
      const cat = APP_META[app.id]?.category ?? 'Other';
      if (!groups[cat]) groups[cat] = [];
      groups[cat].push(app);
    }
    return groups;
  }, [filtered, activeCategory, search]);

  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = { All: apps.length };
    for (const app of apps) {
      const cat = APP_META[app.id]?.category;
      if (cat) counts[cat] = (counts[cat] ?? 0) + 1;
    }
    return counts;
  }, [apps]);

  // Pinned + recent app objects
  const pinnedApps = useMemo(
    () => pinnedAppIds.flatMap((id) => apps.filter((a) => a.id === id)),
    [pinnedAppIds, apps],
  );
  const recentApps = useMemo(
    () => recentAppIds.flatMap((id) => apps.filter((a) => a.id === id)).slice(0, 6),
    [recentAppIds, apps],
  );

  let cardIndex = 0;

  const renderCard = (app: AppDefinition, idx: number) => {
    const meta = APP_META[app.id] ?? { icon: '🔲', description: '', color: theme.colors.accent, category: '' };
    const isPinned = pinnedAppIds.includes(app.id);
    return (
      <Card
        key={app.id}
        accentColor={meta.color}
        index={idx}
        pinned={isPinned}
        onClick={() => onSelect(app)}
      >
        <PinBtn
          className="pin-btn"
          pinned={isPinned}
          role="button"
          title={isPinned ? 'Unpin' : 'Pin to top'}
          onClick={(e) => { e.stopPropagation(); onTogglePin(app.id); }}
        >
          {isPinned ? '📌' : '📍'}
        </PinBtn>
        <CardIcon>{meta.icon}</CardIcon>
        <CardLabel>{app.label}</CardLabel>
        <CardDesc>{meta.description}</CardDesc>
        <CardFooter accentColor={meta.color}>Open →</CardFooter>
      </Card>
    );
  };

  return (
    <>
      <Page>
        <TopBar>
          <TopBarLogo>Atl<span>antis</span></TopBarLogo>
          {user && onSignOut && (
            <UserMenu
              user={{ name: user.name, email: user.email, avatarUrl: user.avatarUrl }}
              onSignOut={onSignOut}
            />
          )}
        </TopBar>
        <Body>
        <Sidebar>
          <SidebarHeading>Categories</SidebarHeading>
          {ALL_CATEGORIES.map((cat) => (
            <SidebarItem key={cat} active={activeCategory === cat} onClick={() => setActiveCategory(cat)}>
              {cat}
              <SidebarCount>{categoryCounts[cat] ?? 0}</SidebarCount>
            </SidebarItem>
          ))}
        </Sidebar>

        <Main>
          <Header>
            <Tagline>A suite of tools — pick where you want to go</Tagline>
            <SearchRow>
              <SearchInput
                ref={searchInputRef}
                placeholder="Search apps…"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              <KbdHint>
                <kbd>⌘</kbd><kbd>K</kbd> to open launcher
              </KbdHint>
            </SearchRow>
          </Header>

          {filtered.length === 0 && (
            <EmptyState>No apps match "{search}"</EmptyState>
          )}

          {/* Pinned section */}
          {!search && pinnedApps.length > 0 && (
            <div>
              <SectionLabel>Pinned</SectionLabel>
              <Grid>
                {pinnedApps.map((app) => renderCard(app, cardIndex++))}
              </Grid>
            </div>
          )}

          {/* Recently used section */}
          {!search && activeCategory === 'All' && recentApps.length > 0 && (
            <div>
              <SectionLabel>Recently used</SectionLabel>
              <Grid>
                {recentApps.map((app) => renderCard(app, cardIndex++))}
              </Grid>
            </div>
          )}

          {/* Main grid — grouped by category or flat */}
          {grouped ? (
            Object.entries(grouped).map(([category, catApps]) => (
              <div key={category}>
                <SectionLabel>{category}</SectionLabel>
                <Grid>
                  {catApps.map((app) => renderCard(app, cardIndex++))}
                </Grid>
              </div>
            ))
          ) : (
            <Grid>
              {filtered.map((app) => renderCard(app, cardIndex++))}
            </Grid>
          )}
        </Main>
        </Body>
      </Page>

      {/* Cmd+K Command Palette */}
      {paletteOpen && (
        <PaletteOverlay onClick={() => setPaletteOpen(false)}>
          <PaletteBox onClick={(e) => e.stopPropagation()}>
            <PaletteInput
              ref={paletteInputRef}
              placeholder="Search apps…"
              value={paletteQuery}
              onChange={(e) => { setPaletteQuery(e.target.value); setPaletteIndex(0); }}
              onKeyDown={handlePaletteKey}
            />
            <PaletteResults>
              {paletteResults.length === 0 && (
                <PaletteEmpty>No results for "{paletteQuery}"</PaletteEmpty>
              )}
              {paletteResults.map((app, i) => {
                const meta = APP_META[app.id] ?? { icon: '🔲', description: '', color: theme.colors.accent, category: '' };
                return (
                  <PaletteItem
                    key={app.id}
                    selected={i === paletteIndex}
                    onMouseEnter={() => setPaletteIndex(i)}
                    onClick={() => { setPaletteOpen(false); onSelect(app); }}
                  >
                    <PaletteIcon>{meta.icon}</PaletteIcon>
                    <PaletteLabel>{app.label}</PaletteLabel>
                    <PaletteDesc>{meta.description}</PaletteDesc>
                    <PaletteCategory>{meta.category}</PaletteCategory>
                  </PaletteItem>
                );
              })}
            </PaletteResults>
            <PaletteFooter>
              <span><kbd>↑</kbd><kbd>↓</kbd> navigate</span>
              <span><kbd>↵</kbd> open</span>
              <span><kbd>Esc</kbd> close</span>
            </PaletteFooter>
          </PaletteBox>
        </PaletteOverlay>
      )}
    </>
  );
}
